import Flutter
import UIKit
import NetworkExtension

@main
@objc class AppDelegate: FlutterAppDelegate {
    private static let vpnChannel = "com.follow.clash/ios_vpn"
    private static let coreChannel = "com.follow.clash/core"

    /// The App Group the app shares with the packet-tunnel extension. The core
    /// runs inside the extension's sandbox, so the data directory has to be
    /// inside this container for both processes to reach the same files.
    private static let appGroupId = "group.com.follow.clash"

    /// The bundle id of the packet-tunnel extension generated by
    /// tool/add_ios_extension.rb. NETunnelProviderManager matches saved
    /// configurations against it, so it must stay in step with the extension
    /// target in the Xcode project.
    private static let providerBundleIdentifier = "com.follow.clash.FlClashService"

    /// The data directory the core works in, mirrored by `VpnCore.groupHomeDir`
    /// on the extension side. Keep the two in step: if they disagree the core
    /// reads a directory the app never wrote to.
    static func groupHomeDir() -> String? {
        guard let container = FileManager.default.containerURL(
            forSecurityApplicationGroupIdentifier: appGroupId
        ) else {
            return nil
        }
        return container
            .appendingPathComponent("Library/Application Support/flclash", isDirectory: true)
            .path
    }

    /// Last manager handed out by `loadTunnelManager`. Only a cache: every
    /// entry point still reloads from preferences when it needs the connection,
    /// so a stale object can never drive a stale tunnel.
    private var cachedManager: NETunnelProviderManager?

    override func application(
        _ application: UIApplication,
        didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
    ) -> Bool {
        GeneratedPluginRegistrant.register(with: self)
        registerChannels()
        return super.application(application, didFinishLaunchingWithOptions: launchOptions)
    }

    // MARK: - Channels

    /// Set once both channels have a handler installed. Only used to decide
    /// whether the activation-time retry below still has work to do.
    private var channelsRegistered = false

    /// Registers the VPN and core method channels.
    ///
    /// The messenger comes from the plugin registrar rather than from
    /// `window?.rootViewController`: the registrar is backed by the engine the
    /// Flutter view runs on, so it is available even when the window is not
    /// wired up yet. Depending on `window` here left both channels unregistered
    /// whenever the app was launched through a UIScene, and every call from Dart
    /// then failed with MissingPluginException.
    private func registerChannels() {
        var messenger: FlutterBinaryMessenger?
        if let registrar = self.registrar(forPlugin: "FlClashChannels") {
            messenger = registrar.messenger()
        } else if let controller = window?.rootViewController as? FlutterViewController {
            messenger = controller.binaryMessenger
        }
        guard let messenger = messenger else {
            return
        }

        let vpn = FlutterMethodChannel(
            name: Self.vpnChannel,
            binaryMessenger: messenger
        )
        vpn.setMethodCallHandler { [weak self] call, result in
            self?.handle(call, result: result)
        }

        // The Go core lives inside the packet-tunnel extension, so core method
        // calls are relayed through sendProviderMessage and answered by the
        // extension's handleAppMessage.
        let core = FlutterMethodChannel(
            name: Self.coreChannel,
            binaryMessenger: messenger
        )
        core.setMethodCallHandler { [weak self] call, result in
            self?.handleCore(call, result: result)
        }

        channelsRegistered = true
    }

    override func applicationDidBecomeActive(_ application: UIApplication) {
        super.applicationDidBecomeActive(application)
        // A UIScene launch only builds the window once the app becomes active,
        // so give the channels a second chance here when the launch-time
        // registration found no messenger.
        if !channelsRegistered {
            registerChannels()
        }
    }

    // MARK: - Method channel dispatch

    private func handle(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
        switch call.method {
        case "getStatus":
            getStatus(result)
        case "saveConfig":
            let args = call.arguments as? [String: Any] ?? [:]
            saveConfig(args, result: result)
        case "start":
            start(result)
        case "stop":
            stop(result)
        case "getRunTime":
            result(runTime.map { Int64($0.timeIntervalSince1970 * 1000) } ?? 0)
        case "setRunTime":
            let args = call.arguments as? [String: Any] ?? [:]
            // Dart sends an int; the standard codec hands it over as NSNumber,
            // so an `as? Double` cast never matched.
            if let ts = args["timestamp"] as? NSNumber {
                runTime = Date(timeIntervalSince1970: ts.doubleValue / 1000)
            }
            result(nil)
        case "requestPermission":
            requestPermission(result)
        case "getHomeDir":
            // The Dart side asks for this instead of path_provider's app
            // container, which the extension cannot read.
            result(Self.groupHomeDir())
        default:
            result(FlutterMethodNotImplemented)
        }
    }

    private var runTime: Date?

    // MARK: - Tunnel configuration

    /// Loads the saved packet-tunnel configuration, creating an empty manager
    /// when the caller is about to write one.
    ///
    /// `NEVPNManager` is deliberately not used here. It owns the Personal VPN
    /// slot (IKEv2/IPsec) and refuses a `NETunnelProviderProtocol`; attaching
    /// one made even `loadFromPreferences` fail with "permission denied", which
    /// is what the app reported as `load_failed`. NETunnelProviderManager is
    /// the API that actually manages provider-based configurations.
    private func loadTunnelManager(
        createIfMissing: Bool,
        completion: @escaping (NETunnelProviderManager?, Error?) -> Void
    ) {
        NETunnelProviderManager.loadAllFromPreferences { managers, error in
            if let error = error {
                completion(nil, error)
                return
            }
            let match = managers?.first { manager in
                (manager.protocolConfiguration as? NETunnelProviderProtocol)?
                    .providerBundleIdentifier == Self.providerBundleIdentifier
            }
            if let match = match {
                completion(match, nil)
            } else if createIfMissing {
                completion(NETunnelProviderManager(), nil)
            } else {
                completion(nil, nil)
            }
        }
    }

    /// Persists the manager and waits until the system has re-read it.
    ///
    /// The reload is mandatory rather than defensive: Apple only exposes a
    /// usable `connection` after `loadFromPreferences` runs again on a freshly
    /// saved manager, and `startVPNTunnel` throws on the un-loaded object.
    private func persist(
        _ manager: NETunnelProviderManager,
        completion: @escaping (Error?) -> Void
    ) {
        manager.isEnabled = true
        manager.saveToPreferences { error in
            if let error = error {
                completion(error)
                return
            }
            manager.loadFromPreferences { reloadError in
                completion(reloadError)
            }
        }
    }

    private func saveConfig(_ args: [String: Any], result: @escaping FlutterResult) {
        loadTunnelManager(createIfMissing: true) { manager, error in
            if let error = error {
                result(FlutterError(code: "load_failed", message: error.localizedDescription, details: nil))
                return
            }
            guard let manager = manager else {
                result(FlutterError(code: "load_failed", message: "no tunnel configuration", details: nil))
                return
            }

            let proto = NETunnelProviderProtocol()
            proto.serverAddress = args["serverAddress"] as? String ?? "127.0.0.1"
            proto.providerBundleIdentifier = Self.providerBundleIdentifier
            proto.disconnectOnSleep = args["disconnectOnSleep"] as? Bool ?? false

            // Pass the Go core config through to the extension.
            var providerConfig: [String: Any] = [
                "stack": args["stack"] as? String ?? "gvisor",
                "address": args["address"] as? String ?? "198.18.0.1/30",
                "dns": args["dns"] as? String ?? "198.18.0.1",
            ]
            // Leave the key out when the caller has no home dir: the extension
            // treats a missing key as "use the App Group container", but an
            // empty string would be taken literally as its data path.
            if let homeDir = args["homeDir"] as? String, !homeDir.isEmpty {
                providerConfig["home-dir"] = homeDir
            }
            if let options = args["options"] as? [String: Any] {
                for (k, v) in options { providerConfig[k] = v }
            }
            proto.providerConfiguration = providerConfig

            manager.protocolConfiguration = proto
            manager.localizedDescription = "FlClash"

            self.persist(manager) { error in
                if let error = error {
                    result(FlutterError(code: "save_failed", message: error.localizedDescription, details: nil))
                } else {
                    self.cachedManager = manager
                    result(true)
                }
            }
        }
    }

    // MARK: - Status

    private func getStatus(_ result: @escaping FlutterResult) {
        loadTunnelManager(createIfMissing: false) { manager, _ in
            // A missing configuration is not an error: it just is not running.
            guard let manager = manager else {
                result(["connected": false, "connecting": false, "running": false])
                return
            }
            let status = manager.connection.status
            let connected = status == .connected
            let connecting = status == .connecting || status == .reasserting
            result([
                "connected": connected,
                "connecting": connecting,
                "running": connected || connecting,
            ])
        }
    }

    // MARK: - Start / Stop

    private func start(_ result: @escaping FlutterResult) {
        loadTunnelManager(createIfMissing: false) { manager, error in
            if let error = error {
                result(FlutterError(code: "load_failed", message: error.localizedDescription, details: nil))
                return
            }
            guard let manager = manager else {
                result(FlutterError(
                    code: "not_configured",
                    message: "save the tunnel configuration before starting",
                    details: nil
                ))
                return
            }
            manager.loadFromPreferences { reloadError in
                if let reloadError = reloadError {
                    result(FlutterError(code: "load_failed", message: reloadError.localizedDescription, details: nil))
                    return
                }
                do {
                    try manager.connection.startVPNTunnel()
                    self.cachedManager = manager
                    self.runTime = Date()
                    result(true)
                } catch {
                    result(FlutterError(code: "start_failed", message: error.localizedDescription, details: nil))
                }
            }
        }
    }

    private func stop(_ result: @escaping FlutterResult) {
        let stopNow: (NETunnelProviderManager?) -> Void = { manager in
            manager?.connection.stopVPNTunnel()
            result(true)
        }
        if let cached = cachedManager {
            stopNow(cached)
        } else {
            loadTunnelManager(createIfMissing: false) { manager, _ in
                stopNow(manager)
            }
        }
    }

    // MARK: - Permission

    private func requestPermission(_ result: @escaping FlutterResult) {
        loadTunnelManager(createIfMissing: true) { manager, error in
            if let error = error {
                result(FlutterError(code: "load_failed", message: error.localizedDescription, details: nil))
                return
            }
            guard let manager = manager else {
                result(FlutterError(code: "load_failed", message: "no tunnel configuration", details: nil))
                return
            }
            // Ask the system to install the configuration. When one already
            // exists this leaves it untouched — overwriting it here would wipe
            // the provider config the tunnel needs.
            if manager.protocolConfiguration == nil {
                let proto = NETunnelProviderProtocol()
                proto.serverAddress = "127.0.0.1"
                proto.providerBundleIdentifier = Self.providerBundleIdentifier
                manager.protocolConfiguration = proto
                manager.localizedDescription = "FlClash"
            }
            self.persist(manager) { error in
                if let error = error {
                    result(FlutterError(code: "permission_failed", message: error.localizedDescription, details: nil))
                } else {
                    self.cachedManager = manager
                    result(true)
                }
            }
        }
    }
}

// MARK: - Core relay
extension AppDelegate {

    /// Relays a JSON core method call (e.g. "getConfig", "changeProxy") to the
    /// Go core inside the tunnel extension and returns its raw JSON reply.
    func handleCore(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
        guard call.method == "invokeMethod" else {
            result(FlutterMethodNotImplemented)
            return
        }
        guard let payload = call.arguments as? String,
              let data = payload.data(using: .utf8) else {
            result(FlutterError(code: "bad_arguments",
                message: "expected a JSON string", details: nil))
            return
        }
        sendThroughTunnel(data, result: result)
    }

    private func sendThroughTunnel(_ data: Data, result: @escaping FlutterResult) {
        if let session = cachedManager?.connection as? NETunnelProviderSession {
            relay(data, over: session, result: result)
            return
        }
        // The cache is empty on a cold start and after a process relaunch, so
        // fall back to the saved configuration before giving up.
        loadTunnelManager(createIfMissing: false) { manager, error in
            if let error = error {
                result(FlutterError(code: "load_failed",
                    message: error.localizedDescription, details: nil))
                return
            }
            guard let manager = manager,
                  let session = manager.connection as? NETunnelProviderSession else {
                result(FlutterError(code: "no_session",
                    message: "the tunnel is not configured or not running", details: nil))
                return
            }
            self.cachedManager = manager
            self.relay(data, over: session, result: result)
        }
    }

    private func relay(
        _ data: Data,
        over session: NETunnelProviderSession,
        result: @escaping FlutterResult,
        attempt: Int = 0
    ) {
        do {
            try session.sendProviderMessage(data) { response in
                // The reply arrives on a background queue; FlutterResult must
                // be invoked on the main thread.
                DispatchQueue.main.async {
                    if let response = response {
                        result(FlutterStandardTypedData(bytes: response))
                    } else {
                        result(nil)
                    }
                }
            }
        } catch {
            // sendProviderMessage refuses to enqueue anything until the tunnel
            // is up, and the app issues its first core call right after
            // start(), so the very first attempt races the handshake. The Dart
            // side only retries for a few hundred milliseconds, which cannot
            // cover a multi-second tunnel setup, so wait here instead.
            let stillStarting = session.status == .connecting || session.status == .reasserting
            if attempt < 24 && stillStarting {
                DispatchQueue.global().asyncAfter(deadline: .now() + 0.25) {
                    self.relay(data, over: session, result: result, attempt: attempt + 1)
                }
                return
            }
            result(FlutterError(code: "send_failed",
                message: error.localizedDescription, details: nil))
        }
    }
}
